/*
 * Optimize the filter code in its dag representation.
 * Return 0 on success, -1 on error.
 */
int
bpf_optimize(struct icode *ic, char *errbuf)
{
        opt_state_t opt_state;

        memset(&opt_state, 0, sizeof(opt_state));
        opt_state.errbuf = errbuf;
        if (setjmp(opt_state.top_ctx)) {
                opt_cleanup(&opt_state);
                return -1;
        }
        opt_init(&opt_state, ic);
        opt_loop(&opt_state, ic, 0);
        opt_loop(&opt_state, ic, 1);
        intern_blocks(&opt_state, ic);
#ifdef BDEBUG
        if (pcap_optimizer_debug > 1 || pcap_print_dot_graph) {
                printf("after intern_blocks()\n");
                opt_dump(&opt_state, ic);
        }
#endif
        opt_root(&ic->root);
#ifdef BDEBUG
        if (pcap_optimizer_debug > 1 || pcap_print_dot_graph) {
                printf("after opt_root()\n");
                opt_dump(&opt_state, ic);
        }
#endif
        opt_cleanup(&opt_state);
        return 0;
}

static void
make_marks(struct icode *ic, struct block *p)
{
        if (!isMarked(ic, p)) {
                Mark(ic, p);
                if (BPF_CLASS(p->s.code) != BPF_RET) {
                        make_marks(ic, JT(p));
                        make_marks(ic, JF(p));
                }
        }
}

/*
 * Mark code array such that isMarked(ic->cur_mark, i) is true
 * only for nodes that are alive.
 */
static void
mark_code(struct icode *ic)
{
        ic->cur_mark += 1;
        make_marks(ic, ic->root);
}

/*
 * True iff the two stmt lists load the same value from the packet into
 * the accumulator.
 */
static int
eq_slist(struct slist *x, struct slist *y)
{
        for (;;) {
                while (x && x->s.code == NOP)
                        x = x->next;
                while (y && y->s.code == NOP)
                        y = y->next;
                if (x == 0)
                        return y == 0;
                if (y == 0)
                        return x == 0;
                if (x->s.code != y->s.code || x->s.k != y->s.k)
                        return 0;
                x = x->next;
                y = y->next;
        }
}

static inline int
eq_blk(struct block *b0, struct block *b1)
{
        if (b0->s.code == b1->s.code &&
            b0->s.k == b1->s.k &&
            b0->et.succ == b1->et.succ &&
            b0->ef.succ == b1->ef.succ)
                return eq_slist(b0->stmts, b1->stmts);
        return 0;
}

